import { sanitizeName, tfLabelToTsLabel } from "../../engine/tf/index.js";
/** Derive connector identity from its own model and provider data blocks. */
export function connectorIdentityFromTf(connectorType, connectorLabel, lookup) {
    const modelName = lookup.dataName(connectorType, connectorLabel);
    const handle = tfLabelToTsLabel(sanitizeName(modelName ?? connectorLabel));
    const providerRef = lookup.dataRef(connectorType, connectorLabel);
    const providerName = providerRef === undefined
        ? undefined
        : lookup.dataName(providerRef.resourceType, providerRef.tfLabel);
    if (providerName === undefined || modelName === undefined)
        return { handle };
    const providerKey = tfLabelToTsLabel(sanitizeName(providerName));
    return { handle, providerKey, catalogKey: `${providerKey}.${handle}` };
}
